create_once(
    "src/main/resources/assets/metallum/shaders/core/particle_previous_motion.vsh",
    '''#version 330\n\n#moj_import <minecraft:dynamictransforms.glsl>\n#moj_import <minecraft:projection.glsl>\n\n// Minecraft 26.2 DefaultVertexFormat.PARTICLE is Position, UV0, Color, UV2. Binding 1 therefore\n// starts PreviousPosition at location 4. The current staged Position is already camera-relative.\nlayout(location = 0) in vec3 Position;\nlayout(location = 1) in vec2 UV0;\nlayout(location = 2) in vec4 Color;\nlayout(location = 4) in vec3 PreviousPosition;\n\nlayout(std140) uniform MetallumMotion {\n    mat4 CurrentUnjitteredFromRaster;\n    mat4 PreviousFromRaster;\n};\n\nnoperspective out vec2 metallumObjectMotion;\nflat out float metallumObjectValidity;\nout vec2 metallumTexCoord;\nflat out float metallumVertexAlpha;\n\nvoid main() {\n    vec4 rasterClip = ProjMat * ModelViewMat * vec4(Position, 1.0);\n    vec4 currentClip = CurrentUnjitteredFromRaster * rasterClip;\n    vec4 previousClip = PreviousFromRaster * vec4(PreviousPosition, 1.0);\n    gl_Position = rasterClip;\n    metallumTexCoord = UV0;\n    metallumVertexAlpha = Color.a;\n\n    bool valid = currentClip.w > 1.0e-6 && previousClip.w > 1.0e-6;\n    if (valid) {\n        vec2 currentNdc = currentClip.xy / currentClip.w;\n        vec2 previousNdc = previousClip.xy / previousClip.w;\n        vec2 motion = vec2(\n            previousNdc.x - currentNdc.x,\n            currentNdc.y - previousNdc.y\n        );\n        valid = !any(isnan(currentNdc)) && !any(isinf(currentNdc))\n            && !any(isnan(previousNdc)) && !any(isinf(previousNdc))\n            && !any(isnan(motion)) && !any(isinf(motion))\n            && all(lessThanEqual(abs(motion), vec2(32.0)));\n        metallumObjectMotion = valid ? motion : vec2(0.0);\n    } else {\n        metallumObjectMotion = vec2(0.0);\n    }\n    metallumObjectValidity = valid ? 1.0 : 0.0;\n}\n'''
)
create_once(
    "src/main/resources/assets/metallum/shaders/core/particle_previous_motion.fsh",
    '''#version 330\n\n#moj_import <minecraft:dynamictransforms.glsl>\n\nuniform sampler2D Sampler0;\n\nnoperspective in vec2 metallumObjectMotion;\nflat in float metallumObjectValidity;\nin vec2 metallumTexCoord;\nflat in float metallumVertexAlpha;\n\nlayout(location = 0) out vec2 metallumMotionTarget;\nlayout(location = 1) out float metallumValidityTarget;\n\nvoid main() {\n    // Match vanilla particle.fsh visibility: texture * vertexColor * ColorModulator, alpha < 0.1\n    // discarded. Lightmap alpha is 1 for the particle vertex-color path, so only RGB lighting is\n    // intentionally irrelevant to the binary coverage decision here.\n    float alpha = texture(Sampler0, metallumTexCoord).a * metallumVertexAlpha * ColorModulator.a;\n    if (alpha < 0.1) {\n        discard;\n    }\n    metallumMotionTarget = metallumObjectMotion;\n    metallumValidityTarget = metallumObjectValidity;\n}\n'''
)

# Transaction tests exercise the exact signature/generation semantics without manufacturing live
# abstract Particle subclasses; source-contract CI separately verifies the extraction/add/batch wiring.
create_once(
    "src/test/java/com/metallum/client/metal/render/MetalParticleBatchMotionTest.java",
    '''package com.metallum.client.metal.render;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.Test;\n\nimport java.util.List;\n\nimport static org.junit.jupiter.api.Assertions.*;\n\nfinal class MetalParticleBatchMotionTest {\n    private static final MetalParticleBatchMotion.LayerSignature OPAQUE_AB =\n            new MetalParticleBatchMotion.LayerSignature(\n                    false, \"minecraft:textures/atlas/particles.png\",\n                    \"minecraft:pipeline/opaque_particle\", \"minecraft:core/particle\",\n                    List.of(11L, 22L)\n            );\n    private static final MetalParticleBatchMotion.LayerSignature OPAQUE_BA =\n            new MetalParticleBatchMotion.LayerSignature(\n                    false, \"minecraft:textures/atlas/particles.png\",\n                    \"minecraft:pipeline/opaque_particle\", \"minecraft:core/particle\",\n                    List.of(22L, 11L)\n            );\n    private static final MetalParticleBatchMotion.Signature SIG_AB =\n            new MetalParticleBatchMotion.Signature(false, List.of(OPAQUE_AB));\n\n    @AfterEach\n    void reset() {\n        MetalParticleBatchMotion.reset();\n    }\n\n    @Test\n    void stableLayerAndParticleOrderReuseExactHistory() {\n        MetalParticleBatchMotion.beginFrame();\n        MetalEntityMotionCapture.Sample first = MetalParticleBatchMotion.beginSignatureBatch(SIG_AB);\n        assertNotNull(first);\n        assertFalse(first.hasPrevious());\n        assertTrue(first.generation() < 0L);\n        MetalParticleBatchMotion.commitSubmittedFrame();\n\n        MetalParticleBatchMotion.beginFrame();\n        MetalEntityMotionCapture.Sample second = MetalParticleBatchMotion.beginSignatureBatch(SIG_AB);\n        assertNotNull(second);\n        assertEquals(first.objectId(), second.objectId());\n        assertEquals(first.generation(), second.generation());\n        assertTrue(second.hasPrevious());\n    }\n\n    @Test\n    void sameCountButParticleOrderChangeAllocatesFreshGeneration() {\n        MetalParticleBatchMotion.beginFrame();\n        MetalEntityMotionCapture.Sample first = MetalParticleBatchMotion.beginSignatureBatch(SIG_AB);\n        assertNotNull(first);\n        MetalParticleBatchMotion.commitSubmittedFrame();\n\n        MetalParticleBatchMotion.Signature reordered =\n                new MetalParticleBatchMotion.Signature(false, List.of(OPAQUE_BA));\n        MetalParticleBatchMotion.beginFrame();\n        MetalEntityMotionCapture.Sample changed = MetalParticleBatchMotion.beginSignatureBatch(reordered);\n        assertNotNull(changed);\n        assertNotEquals(first.generation(), changed.generation());\n        assertFalse(changed.hasPrevious());\n    }\n\n    @Test\n    void layerOrTransparencyChangeBreaksContinuity() {\n        MetalParticleBatchMotion.beginFrame();\n        MetalEntityMotionCapture.Sample first = MetalParticleBatchMotion.beginSignatureBatch(SIG_AB);\n        assertNotNull(first);\n        MetalParticleBatchMotion.commitSubmittedFrame();\n\n        MetalParticleBatchMotion.LayerSignature otherAtlas =\n                new MetalParticleBatchMotion.LayerSignature(\n                        false, \"minecraft:textures/atlas/blocks.png\",\n                        \"minecraft:pipeline/opaque_particle\", \"minecraft:core/particle\",\n                        List.of(11L, 22L));\n        MetalParticleBatchMotion.beginFrame();\n        assertFalse(MetalParticleBatchMotion.beginSignatureBatch(\n                new MetalParticleBatchMotion.Signature(false, List.of(otherAtlas))).hasPrevious());\n\n        MetalParticleBatchMotion.reset();\n        MetalParticleBatchMotion.beginFrame();\n        assertNotNull(MetalParticleBatchMotion.beginSignatureBatch(SIG_AB));\n        MetalParticleBatchMotion.commitSubmittedFrame();\n        MetalParticleBatchMotion.beginFrame();\n        assertFalse(MetalParticleBatchMotion.beginSignatureBatch(\n                new MetalParticleBatchMotion.Signature(true, List.of(OPAQUE_AB))).hasPrevious());\n    }\n\n    @Test\n    void discardedFrameDoesNotAdvanceButSubmittedGapBreaksContinuity() {\n        MetalParticleBatchMotion.beginFrame();\n        MetalEntityMotionCapture.Sample first = MetalParticleBatchMotion.beginSignatureBatch(SIG_AB);\n        assertNotNull(first);\n        MetalParticleBatchMotion.commitSubmittedFrame();\n\n        MetalParticleBatchMotion.beginFrame();\n        MetalParticleBatchMotion.Signature reordered =\n                new MetalParticleBatchMotion.Signature(false, List.of(OPAQUE_BA));\n        assertNotNull(MetalParticleBatchMotion.beginSignatureBatch(reordered));\n        MetalParticleBatchMotion.discardFrame();\n\n        MetalParticleBatchMotion.beginFrame();\n        MetalEntityMotionCapture.Sample recovered = MetalParticleBatchMotion.beginSignatureBatch(SIG_AB);\n        assertTrue(recovered.hasPrevious());\n        assertEquals(first.generation(), recovered.generation());\n        MetalParticleBatchMotion.commitSubmittedFrame();\n\n        MetalParticleBatchMotion.beginFrame();\n        MetalParticleBatchMotion.commitSubmittedFrame();\n        MetalParticleBatchMotion.beginFrame();\n        assertFalse(MetalParticleBatchMotion.beginSignatureBatch(SIG_AB).hasPrevious());\n    }\n\n    @Test\n    void particleObjectIdentityAllocatorIsPositiveAndUnique() {\n        long first = MetalParticleBatchMotion.allocateParticleIdentity();\n        long second = MetalParticleBatchMotion.allocateParticleIdentity();\n        assertTrue(first > 0L);\n        assertTrue(second > first);\n    }\n}\n'''
)

